#!/usr/bin/env node
// A1004: copy-only extraction of lana declarations by file:line/name.
// Generated files are DRAFT copy-only blocks, not adapted and not compiled.
import fs from 'node:fs';
import path from 'node:path';
const ROOT = 'D:/lean';
const OUT = 'D:/lean/tmp/sheaf/xif/paper';
const TARGETS = [
  { out: 'Mzk1PortedVcIDefsActual.lean',
    namespace: 'LeanFormal.IUT.XiFPaper.Mzk1PortedVcIDefsActual',
    src: 'Iut/WallEquiv/VcI.lean',
    decls: ['orderVol','shellExcess','logShellRadius','defectPacket','logVol_hull_vcI_eq','hullPacket_finite','hullPacket_tame'] },
  { out: 'Mzk1PortedGapDefsActual.lean',
    namespace: 'LeanFormal.IUT.XiFPaper.Mzk1PortedGapDefsActual',
    src: 'Iut/WallEquiv/Gap.lean',
    decls: ['archDefect','ind2Term','ind2Term_nonneg','gapHullAt'] },
  { out: 'Mzk1PortedIdentifiedCopiesDefsActual.lean',
    namespace: 'LeanFormal.IUT.XiFPaper.Mzk1PortedIdentifiedCopiesDefsActual',
    src: 'Iut/Wall/IdentifiedCopies.lean',
    decls: ['componentVol_units_smul'] },
];
function declStart(line) {
  const t = line.trim();
  const m = t.match(/^(?:@\[[^\]]*\]\s*)?(?:(?:noncomputable|protected|private)\s+)*(?:def|theorem|lemma|abbrev|structure|instance)\s+([^\s:{([]+)/);
  if (!m) return null;
  return { name: m[1].replace(/^_root_\./, ''), indent: line.length - line.trimStart().length };
}
function isBoundary(t) {
  const s = t.trim();
  return s.startsWith('namespace ') || s.startsWith('end') || s.startsWith('section') ||
    /^(?:@\[[^\]]*\]\s*)?(?:(?:noncomputable|protected|private)\s+)*(?:def|theorem|lemma|abbrev|structure|instance)\s+/.test(s);
}
function extractBlock(lines, declName) {
  for (let i = 0; i < lines.length; i++) {
    const d = declStart(lines[i]);
    if (!d || d.name !== declName) continue;
    let start = i;
    let j = i - 1;
    while (j >= 0 && lines[j].trim() === '') j--;
    if (j >= 0) {
      const last = lines[j].trim();
      if (last.endsWith('-/') || last.startsWith('--')) {
        let k = j;
        while (k >= 0) {
          const s = lines[k].trim();
          if (s.startsWith('/-') || s.startsWith('--')) { start = k; if (s.startsWith('/-')) break; }
          k--;
        }
      }
    }
    let end = lines.length;
    for (let k = i + 1; k < lines.length; k++) {
      const t = lines[k];
      if (t.trim() === '') continue;
      const ind = t.length - t.trimStart().length;
      if (ind <= d.indent && isBoundary(t)) { end = k; break; }
    }
    return { startLine: i + 1, block: lines.slice(start, end).join('\n') };
  }
  return { error: declName };
}
for (const target of TARGETS) {
  const srcPath = path.join(ROOT, target.src);
  const lines = fs.readFileSync(srcPath, 'utf8').split(/\r?\n/);
  const blocks = [];
  const missing = [];
  for (const name of target.decls) {
    const r = extractBlock(lines, name);
    if (r.error) missing.push(r.error);
    else blocks.push('-- ===== copy-only: ' + name + ' (source line ' + r.startLine + ') =====\n' + r.block);
  }
  const header = [
    '/- Copyright (c) 2026 LeanFormal contributors. All rights reserved. -/',
    '/- Copy-only extraction (A1004) from LANA root tree:',
    '   ' + target.src + ' (Apache-2.0; Authors LANA Project).',
    '   Generated by tools/extract_lana_defs.mjs; NOT adapted, NOT compiled.',
    '   Identifiers/imports/proofs refer to the original lana context; this file is',
    '   a draft for Phase 4 copy-only definitions, not a green file.',
    '   Namespace changed to ' + target.namespace + '. -/',
    '',
    'import Mathlib',
    '',
    'namespace ' + target.namespace,
    '',
    blocks.join('\n\n'),
    '',
    '-- Extraction report: ' + target.decls.length + ' requested, ' +
      (target.decls.length - missing.length) + ' found, ' + missing.length + ' missing.',
    missing.length ? '-- MISSING: ' + missing.join('; ') : '-- all requested declarations found.',
    '',
    'end ' + target.namespace,
    ''
  ].join('\n');
  fs.writeFileSync(path.join(OUT, target.out), header);
  console.log(target.out + ': ' + (target.decls.length - missing.length) + '/' + target.decls.length +
    (missing.length ? ' missing=' + missing.join('; ') : ''));
}